"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["21629"],{76034(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.referencia_temporal_fatos_extremo_ausente","status":422,"titulo":"A fase da refer\xeancia temporal de fatos n\xe3o tem o extremo (in\xedcio/fim) definido"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.referencia_temporal_fatos_extremo_ausente","requisitos":[],"oQueAconteceu":["A refer\xeancia temporal dos fatos do processo conta a idade do candidato a partir\\ndo in\xedcio ou do fim de uma fase, mas essa fase n\xe3o tem definida a data do\\nextremo escolhido. Se a refer\xeancia \xe9 o in\xedcio da fase, falta o in\xedcio; se \xe9 o\\nfim, falta o fim. O sistema n\xe3o assume outra data no lugar.","A confer\xeancia s\xf3 vale quando alguma regra do processo cita a faixa et\xe1ria do\\ncandidato. A recusa acontece ao tentar congelar uma vers\xe3o (publica\xe7\xe3o inicial ou retifica\xe7\xe3o em ato \xfanico), e nada \xe9 congelado.\\nA mensagem da resposta diz qual extremo falta."],"comoResolver":["Defina no cronograma a data de in\xedcio ou de fim da fase escolhida como\\nrefer\xeancia, conforme o extremo que a refer\xeancia usa. Alternativamente, defina de\\nnovo a refer\xeancia temporal dos fatos com outra fase ou outro tipo de refer\xeancia.","Se nenhuma regra deveria usar a faixa et\xe1ria, remover a regra que a cita tamb\xe9m\\nafasta a recusa.","Em processo j\xe1 publicado, a altera\xe7\xe3o \xe9 feita numa retifica\xe7\xe3o. Depois, repita a\\nopera\xe7\xe3o recusada."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);